func TestDoRejectsDataForSEOEnvelopeErrors(t *testing.T) {
	tests := []struct {
		name      string
		body      string
		wantScope string
		wantCode  int
	}{
		{
			name:      "top-level error",
			body:      `{"status_code":40501,"status_message":"Invalid field","tasks":[]}`,
			wantScope: "response",
			wantCode:  40501,
		},
		{
			name:      "task error",
			body:      `{"status_code":20000,"status_message":"Ok.","tasks":[{"status_code":40501,"status_message":"Invalid task"}]}`,
			wantScope: "task",
			wantCode:  40501,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
				w.Header().Set("Content-Type", "application/json")
				_, _ = io.WriteString(w, tt.body)
			}))
			defer srv.Close()

			_, _, err := testClient(srv.URL).Post("/v3/test", map[string]any{"value": 1})
			var apiErr *DataForSEOError
			if !errors.As(err, &apiErr) {
				t.Fatalf("Post error = %v, want *DataForSEOError", err)
			}
			if apiErr.Scope != tt.wantScope || apiErr.StatusCode != tt.wantCode {
				t.Fatalf("DataForSEOError = %#v, want scope %q code %d", apiErr, tt.wantScope, tt.wantCode)
			}
		})
	}
}

