func TestGetFreshBypassesCacheAndOnResponseTracksOnlyValidatedLiveResponses(t *testing.T) {
	sequence := 0
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		sequence++
		_, _ = io.WriteString(w, `{"sequence":`+strconv.Itoa(sequence)+`}`)
	}))
	defer srv.Close()

	c := testClient(srv.URL)
	c.NoCache = false
	c.cacheDir = t.TempDir()
	callbackCalls := 0
	c.OnResponse = func(path string, data json.RawMessage) error {
		callbackCalls++
		if path != "/v3/results" || len(data) == 0 {
			t.Errorf("OnResponse(%q, %s)", path, data)
		}
		return nil
	}

	first, err := c.Get("/v3/results", nil)
	if err != nil {
		t.Fatalf("first Get: %v", err)
	}
	cached, err := c.Get("/v3/results", nil)
	if err != nil {
		t.Fatalf("cached Get: %v", err)
	}
	fresh, err := c.GetFresh("/v3/results", nil)
	if err != nil {
		t.Fatalf("GetFresh: %v", err)
	}
	stillCached, err := c.Get("/v3/results", nil)
	if err != nil {
		t.Fatalf("Get after GetFresh: %v", err)
	}

	if string(first) != `{"sequence":1}` || string(cached) != string(first) {
		t.Fatalf("initial cache values = %s and %s", first, cached)
	}
	if string(fresh) != `{"sequence":2}` {
		t.Fatalf("GetFresh = %s, want live sequence 2", fresh)
	}
	if string(stillCached) != string(first) {
		t.Fatalf("GetFresh overwrote cache: subsequent Get = %s, want %s", stillCached, first)
	}
	if c.NoCache {
		t.Fatal("GetFresh mutated Client.NoCache")
	}
	if callbackCalls != 2 {
		t.Fatalf("OnResponse calls = %d, want 2 live responses", callbackCalls)
	}
}

